import numpy as np

class WavyBasin:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Quadratic basin with wavy perturbations
        quadratic = np.sum(x**2)
        # Wavy pattern with increasing amplitude toward center
        wavy = np.sum(np.sin(5 * np.pi * x) * (1 - np.exp(-0.2 * np.sum(x**2))))
        return quadratic + 0.1 * wavy
